               ("عرض اليوم", "اطلب اليوم واستفد من العرض الحالي.", "خصم على أول طلب"),
               [("كيف أطلب؟", "اختر المنتج واضغط «اطلب الآن» ثم املأ بياناتك وسنؤكّد طلبك."), ("هل الدفع عند الاستلام؟", "نعم، تدفع بعد استلام طلبك ومعاينته."), ("كم يستغرق التوصيل؟", "من 24 إلى 72 ساعة حسب ولايتك."), ("هل يمكن الاستبدال؟", "نعم وفق شروط الاستبدال المكتوبة في المتجر.")],
               "%s: متجر إلكتروني بتوصيل لكل الولايات والدفع عند الاستلام." % N["brand"], "السبت – الخميس: 9ص – 8م", "الجزائر — التوصيل لكل الولايات",
